table inet ha_access {
  chain input {
    type filter hook input priority filter; policy drop;
    iifname "lo" accept
    ct state established,related accept
    iifname "enp1s0" udp dport 68 accept
    ip saddr 10.100.15.0/24 tcp dport 22 accept
    ip saddr 10.50.1.0/24 tcp dport { 5432, 8008, 2379, 2380 } accept
    ip saddr 10.50.2.0/24 tcp dport { 5432, 8008, 2379, 2380 } accept
  }
  chain forward {
    type filter hook forward priority filter; policy accept;
  }
  chain output {
    type filter hook output priority filter; policy accept;
  }
}
ANTRIEB_EOF
nft -c -f /etc/nftables.conf && nft -f /etc/nftables.conf && systemctl enable nftables
